function bfsOrder(n, edges, start) {
  const adj = [];
  for (let i = 0; i < n; i++) adj.push([]);
  for (const e of edges) { adj[e[0]].push(e[1]); adj[e[1]].push(e[0]); }
  for (const l of adj) l.sort(function (a, b) { return a - b; });
  const seen = new Array(n).fill(false);
  const order = [];
  const queue = [start];
  seen[start] = true;
  let head = 0;
  while (head < queue.length) {
    const v = queue[head++];
    order.push(v);
    for (const w of adj[v]) if (!seen[w]) { seen[w] = true; queue.push(w); }
  }
  return order;
}

