  // traverse each unvisited component, carrying the vertex you arrived from
  return false;
}

graph-problems.solution:
function hasCycleUndirected(n, edges) {
  const adj = [];
  for (let i = 0; i < n; i++) adj.push([]);
  for (const e of edges) { adj[e[0]].push(e[1]); adj[e[1]].push(e[0]); }
  const seen = new Array(n).fill(false);
  for (let s = 0; s < n; s++) {
    if (seen[s]) continue;
    const stack = [[s, -1]];
    seen[s] = true;
    while (stack.length) {
      const top = stack.pop();
      const v = top[0], parent = top[1];
      for (const w of adj[v]) {
        if (w === parent) continue;
        if (seen[w]) return true;
        seen[w] = true;
        stack.push([w, v]);
      }
    }
  }
  return false;
}

