function pathCost(n, edges, path) {
  const w = [];
  for (let i = 0; i < n; i++) w.push(new Map());
  for (const e of edges) {
    w[e[0]].set(e[1], e[2]);
    w[e[1]].set(e[0], e[2]);
  }
  let total = 0;
  for (let i = 1; i < path.length; i++) {
    const from = path[i - 1], to = path[i];
    if (!w[from].has(to)) return -1;
    total += w[from].get(to);
  }
  return total;
}

