  // record where each vertex sits, checking it is a permutation as you go,
  // then test every edge against those positions
  return false;
}

exam.solution:
function isValidTopoOrder(n, edges, order) {
  if (order.length !== n) return false;
  const pos = new Array(n).fill(-1);
  for (let i = 0; i < order.length; i++) {
    const v = order[i];
    if (v < 0 || v >= n || pos[v] !== -1) return false;
    pos[v] = i;
  }
  for (const e of edges) if (pos[e[0]] >= pos[e[1]]) return false;
  return true;
}
